state.definition:
-- 开始一次运行
  Start: RequestNo ==> StartOutcome
  Start(r) ==
    if r in set dom byRequest then return mk_Started(byRequest(r))
    else let id = NewId() in (byRequest := byRequest ++ {r |-> id}; live := live union {id}; return mk_Started(id));

-- 追加一条尝试
  Record: Entry ==> ()
  Record(e) == (entries := entries ^ [e]; if len entries > 1000 then entries := tl entries);

-- 找回运行
  Status: RequestNo ==> StatusOutcome
  Status(r) == (dcl i : nat := 1; while i <= len cache do (if cache(i).req = r then return cache(i).run; i := i + 1); return <Absent>);

