export type BucketRef = {
  readonly runtime: RuntimeId;
};

pub struct Ticket {
    pub responsible: Principal,
    pub versions: Vec<Version>,
    pub basis: Set<LogPosition>,
}

pub enum DerivationNode {
    Const(Value),
    Field { input: InputId, path: FieldPath },
    Window { size: usize, inner: Box<DerivationNode> },
}

fn sma(xs: &[f64], n: usize) -> Vec<f64> {
    let mut out = Vec::new();
    for w in xs.windows(n) { out.push(w.iter().sum::<f64>() / n as f64); }
    out
}

trait Rule {
    type State;
    fn step(&self, ctx: &Ctx, s: Self::State, i: Input) -> Result<(Self::State, Vec<Outcome>), Rejection>;
}

interface Workspace {
  open(runtime: RuntimeId): Promise<Result<Handle, Failure>>;
  close(handle: Handle): Promise<void>;
}

